import{_ as e,I as a,g as o,j as n}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"Global Settings","description":"Changing the interface language, accounting currency, and data rescue/reset tools in OmniCraft ERP.","frontmatter":{"title":"Global Settings","description":"Changing the interface language, accounting currency, and data rescue/reset tools in OmniCraft ERP.","order":16},"headers":[],"relativePath":"docs/global-settings.md","filePath":"docs/global-settings.md"}'),i={name:"docs/global-settings.md"};function r(s,t,l,c,u,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="⚙️-global-settings-language-currency-and-security" tabindex="-1">⚙️ Global Settings: Language, Currency, and Security <a class="header-anchor" href="#⚙️-global-settings-language-currency-and-security" aria-label="Permalink to &quot;⚙️ Global Settings: Language, Currency, and Security&quot;">​</a></h1><p>Unlike <em>Workspace Settings</em>, which affect the economics of a specific business (rates, markups, overhead costs), <strong>Global Settings</strong> establish the fundamental rules of operation for the entire application and your local database.</p><p>To open them, click <strong>File ➔ Program Settings</strong> in the top menu.</p><hr><h2 id="🌍-localization-and-currency" tabindex="-1">🌍 Localization and Currency <a class="header-anchor" href="#🌍-localization-and-currency" aria-label="Permalink to &quot;🌍 Localization and Currency&quot;">​</a></h2><h3 id="_1-interface-language" tabindex="-1">1. Interface Language <a class="header-anchor" href="#_1-interface-language" aria-label="Permalink to &quot;1. Interface Language&quot;">​</a></h3><p>The program supports full interface localization. Upon its very first launch, OmniCraft ERP automatically scans your operating system&#39;s language and adapts to it. You can switch between <strong>Russian (RU)</strong> and <strong>English (EN)</strong> at any time.</p><ul><li><strong>How it works:</strong> Changing the language requires a full restart of the application so that all system windows, cash flow categories, and directories are properly translated and loaded from the dictionary databases.</li></ul><h3 id="_2-accounting-currency" tabindex="-1">2. Accounting Currency <a class="header-anchor" href="#_2-accounting-currency" aria-label="Permalink to &quot;2. Accounting Currency&quot;">​</a></h3><p>By default, the program pulls your national currency symbol from your OS regional settings (e.g., <code>₽</code>, <code>$</code>, <code>€</code>, <code>£</code>, <code>₺</code>). You can change it to any other currency using the convenient built-in search tool (just start typing the name, such as <em>“Euro”</em> or <em>“Lira”</em>).</p><div class="warning custom-block"><p class="custom-block-title">Protecting Historical Data</p><p>The currency change button is <strong>automatically locked</strong> as soon as you begin recording real transactions (the moment you register your first purchase, sale, or cash flow entry).</p><p>This is done to protect your financial reporting. If the program allowed you to switch currencies on the fly, all your previous receipts, balances, and analytical charts would instantly become a mathematical mess. <strong>What if you relocate to another country?</strong> You will need to perform an &quot;Accounting Reset&quot; (see below) to start keeping books in the new currency from a clean slate, while preserving your existing directories and recipes.</p></div><hr><h2 id="🤖-ai-features-core-ai-hub-byok" tabindex="-1">🤖 AI Features (Core AI Hub &amp; BYOK) <a class="header-anchor" href="#🤖-ai-features-core-ai-hub-byok" aria-label="Permalink to &quot;🤖 AI Features (Core AI Hub &amp; BYOK)&quot;">​</a></h2><p>OmniCraft ERP includes intelligent assistant features powered by artificial intelligence under the <strong>BYOK model (Bring Your Own Key)</strong>.</p><p>All requests to neural network providers are transmitted <strong>directly from your device</strong> to the provider&#39;s API. Your business records, proprietary recipes, client lists, and financial reports never pass through intermediate OmniCraft ERP proxy servers, ensuring 100% data privacy and security.</p><h3 id="_1-supported-ai-providers" tabindex="-1">1. Supported AI Providers <a class="header-anchor" href="#_1-supported-ai-providers" aria-label="Permalink to &quot;1. Supported AI Providers&quot;">​</a></h3><ul><li><strong>OpenAI</strong> (GPT-4o, GPT-4o-mini, o1, o3-mini);</li><li><strong>DeepSeek</strong> (DeepSeek-Chat, DeepSeek-Reasoner / R1);</li><li><strong>Google Gemini</strong> (Gemini 1.5 Flash, Gemini 1.5 Pro, Gemini 2.0);</li><li><strong>OpenRouter</strong> (access to dozens of top models via a single API key);</li><li><strong>Custom Endpoint / Local Ollama</strong> (fully private and offline execution).</li></ul><h3 id="_2-hardware-level-key-protection-windows-dpapi" tabindex="-1">2. Hardware-Level Key Protection (Windows DPAPI) <a class="header-anchor" href="#_2-hardware-level-key-protection-windows-dpapi" aria-label="Permalink to &quot;2. Hardware-Level Key Protection (Windows DPAPI)&quot;">​</a></h3><p>Your API key is encrypted on disk using native operating system cryptographic protection (<strong>Windows Data Protection API — DPAPI</strong>). The encrypted secret is bound to your user account and computer hardware, preventing unauthorized extraction by third-party utilities or configuration file leaks.</p><h3 id="_3-assistant-buttons-spark-buttons-✨-in-workspaces" tabindex="-1">3. Assistant Buttons (&quot;Spark Buttons&quot; ✨) in Workspaces <a class="header-anchor" href="#_3-assistant-buttons-spark-buttons-✨-in-workspaces" aria-label="Permalink to &quot;3. Assistant Buttons (&quot;Spark Buttons&quot; ✨) in Workspaces&quot;">​</a></h3><p>When AI is configured, smart assistant buttons become available in key modules:</p><ul><li><strong>Batch Calculator:</strong> in-depth cost structure audit, identification of main cost drivers, and batch pricing advice.</li><li><strong>Materials Warehouse:</strong> instant generation of technical item descriptions, specifications, and storage recommendations.</li><li><strong>Production Workbench:</strong> operational checklist for the craftsman with quality checkpoints and raw material risk assessments.</li></ul><p>If an API key is not yet configured, clicking any assistant button presents a gentle shortcut dialog to the Settings window without disrupting your current workflow. The application remains 100% functional without AI.</p><h3 id="_4-built-in-ai-assistant-right-sidebar-panel" tabindex="-1">4. Built-in AI Assistant (Right Sidebar Panel) <a class="header-anchor" href="#_4-built-in-ai-assistant-right-sidebar-panel" aria-label="Permalink to &quot;4. Built-in AI Assistant (Right Sidebar Panel)&quot;">​</a></h3><p>A sliding assistant panel is docked to the right edge of the main application window.</p><ul><li><strong>Non-intrusive by Default:</strong> The panel remains collapsed into a slim 38px bar with a compact icon, never distracting the craftsman or cluttering the workspace.</li><li><strong>Screen Context Awareness:</strong> The assistant detects the active module (Warehouse, Workbench, Calculator, Sales) and grounds its responses in current stock and configuration. You can disable screen context at any time using the header toggle or click the preview icon to inspect the exact data snapshot sent to the model.</li><li><strong>Human-in-the-Loop Safety (Zero-Destruction):</strong> When the assistant proposes an operational action (such as generating links or updating records), it presents a structured action card. Mutating operations are executed <strong>only after your explicit confirmation</strong> via the &quot;Execute&quot; button.</li><li><strong>Private Mode:</strong> When connected to a local model (such as Ollama), a green &quot;Offline&quot; badge confirms that processing takes place entirely on your device without internet transmission.</li></ul><h3 id="_5-external-ai-agents-mcp-stdio-server" tabindex="-1">5. External AI Agents (MCP Stdio Server) <a class="header-anchor" href="#_5-external-ai-agents-mcp-stdio-server" aria-label="Permalink to &quot;5. External AI Agents (MCP Stdio Server)&quot;">​</a></h3><p>OmniCraft ERP supports the standardized Model Context Protocol (MCP, 2024-11-05 specification) for interaction with external autonomous agents. This enables external developer tools and agent clients (Cursor, Claude Desktop, Antigravity) to communicate directly with the application via local inter-process communication (<code>stdio</code>).</p><ul><li><strong>Unified Entry Point:</strong> All registered application modules expose their tools through a single central registry. An external agent connects with a single configuration snippet and accesses capabilities across the entire system.</li><li><strong>Pairing Token and One-Click Revocation:</strong> For secure pairing, the settings window generates a unique cryptographic pairing token. If you need to terminate agent access, simply click &quot;Revoke Token&quot;—external connections are immediately invalidated.</li><li><strong>Ready-to-Copy Configuration:</strong> Clicking &quot;Copy JSON Config&quot; generates a standard JSON configuration snippet ready for insertion into your agent configuration (<code>claude_desktop_config.json</code> or Cursor <code>mcp.json</code>).</li><li><strong>Trusted Mode (Protection Against Unauthorized Changes):</strong> By default, external agents are restricted to safe read-only operations. Any mutating operations (such as link generation or record updates) are blocked at the core registry level. To allow modifications, you must explicitly enable &quot;Trusted Mode&quot; in the Program Settings.</li><li><strong>End-to-End Audit Trail:</strong> Every agent invocation is recorded in the system audit log with caller identity, tool name, input arguments, status, and execution latency in milliseconds.</li></ul><hr><h2 id="☢️-danger-zone" tabindex="-1">☢️ Danger Zone <a class="header-anchor" href="#☢️-danger-zone" aria-label="Permalink to &quot;☢️ Danger Zone&quot;">​</a></h2><p>At the bottom of the settings window, you will find tools for radical database interventions. These buttons should be used with extreme caution.</p><h3 id="🧹-accounting-reset-wiping-transaction-history" tabindex="-1">🧹 Accounting Reset (Wiping Transaction History) <a class="header-anchor" href="#🧹-accounting-reset-wiping-transaction-history" aria-label="Permalink to &quot;🧹 Accounting Reset (Wiping Transaction History)&quot;">​</a></h3><p>This tool is designed to <strong>&quot;zero out&quot; the operational memory</strong> of the business without losing its infrastructure. It is ideal if you have been using the program in a trial/test mode, recorded many test receipts, and now want to start keeping real books from a clean slate.</p><table tabindex="0"><thead><tr><th style="text-align:left;">What will be DELETED (Logs)</th><th style="text-align:left;">What will be ZEROED (Balances)</th><th style="text-align:left;">What will be SAVED (Infrastructure)</th></tr></thead><tbody><tr><td style="text-align:left;">• Entire sales history (receipts)</td><td style="text-align:left;">• Physical materials stock in warehouse</td><td style="text-align:left;">• All equipment &amp; assets (Workshop)</td></tr><tr><td style="text-align:left;">• Inventory movement logs</td><td style="text-align:left;">• Finished goods stock (Showcase)</td><td style="text-align:left;">• Materials directories &amp; supplier links</td></tr><tr><td style="text-align:left;">• Cash flow ledger (Cash Flow)</td><td style="text-align:left;">• Cash register balances &amp; Cash Flow history</td><td style="text-align:left;">• All product templates &amp; Recipes</td></tr><tr><td style="text-align:left;">• Production queue (Workbench)</td><td style="text-align:left;">• FIFO batch cost values</td><td style="text-align:left;">• Categories, pack types, global settings</td></tr></tbody></table><p>Prior to performing the wipe, the program will automatically create a shadow backup of the database. After clicking <strong>&quot;Clear History&quot;</strong> (Accounting Reset), OmniCraft ERP will prompt an automatic reboot. You will receive a clean workshop, ready for the initial stock inventory (see <a href="./getting-started">Quick Start</a>).</p><h3 id="💥-factory-reset" tabindex="-1">💥 Factory Reset <a class="header-anchor" href="#💥-factory-reset" aria-label="Permalink to &quot;💥 Factory Reset&quot;">​</a></h3><p>This is the &quot;red pill&quot; button—the ultimate database reset. It <strong>permanently deletes absolutely everything</strong> from your local SQLite database.</p><ul><li>All tables, directories, recipes, receipts, stock balances, settings, and license keys vanish completely.</li><li>Upon the next startup, the program will generate a brand new database, exactly as if you had just downloaded and installed OmniCraft ERP for the very first time.</li></ul><div class="danger custom-block"><p class="custom-block-title">Attention!</p><p>Before using this function, <strong>always</strong> make a manual data export (<code>File ➔ Export Data ➔ Backup Database .db</code>) if there is even a slight chance you might need this information in the future. Recovering data after a factory reset without a backup file is impossible.</p></div><hr><h2 id="🔄-automatic-reboot" tabindex="-1">🔄 Automatic Reboot <a class="header-anchor" href="#🔄-automatic-reboot" aria-label="Permalink to &quot;🔄 Automatic Reboot&quot;">​</a></h2><p>Any changes in the Global Settings (changing the language, currency, or resetting accounts) require a reconfiguration of the operational memory. After saving changes, the program will prompt you to <strong>reboot now</strong> or do it later.</p><p>During the reboot, OmniCraft ERP carefully preserves your window geometry (size and position on the screen), allowing you to resume your work exactly where you left off.</p>',44)])])}const p=e(i,[["render",r]]);export{h as __pageData,p as default};
